    // --- Field help: the longer explanation behind a "?" (ADMIN-UI.md) -------
    // Written for somebody who has never run a website. Double quotes where a
    // blank line starts a new paragraph.
    'help.settings.general' => "Hier vul je in wie je website is: de naam, het logo en hoe mensen je kunnen bereiken.\n\nAlleen de <strong>naam van de website</strong> is verplicht. Al het andere vul je in als je het wilt gebruiken; wat leeg blijft, verschijnt nergens.",
    'help.settings.site_name' => "De naam van je website, zoals bezoekers je kennen. Dat hoeft geen officiële bedrijfsnaam te zijn: een persoonlijke website heeft gewoon een naam.\n\nDe naam staat in het tabblad van de browser, in zoekresultaten zoals die van Google (achter de titel van een pagina), onderaan de website en als afzender van de e-mails die de website verstuurt. Daarom is dit het enige veld op deze pagina dat je moet invullen.",
    'help.settings.kvk_number' => "Het nummer waaronder je bedrijf bij de Kamer van Koophandel (KVK) is ingeschreven. Het bestaat uit acht cijfers.\n\nStaat je bedrijf ingeschreven, dan hoort dit nummer meestal op je website. Het staat dan onderaan de website; dat kun je uitzetten bij <strong>Footer</strong>. Heb je geen KVK-inschrijving, bijvoorbeeld voor een persoonlijke website, laat het dan leeg.",
    'help.settings.email' => "Het algemene e-mailadres van je website. Je hoeft het niet in te vullen, maar zonder dit adres kan de website je geen berichten sturen.\n\nBerichten die bezoekers via een formulier sturen, komen hier binnen als je bij dat formulier geen eigen adres invult. De e-mails die de website verstuurt, komen ook van dit adres, tenzij je hostingpartij een ander afzenderadres heeft ingesteld.\n\nBezoekers zien het adres onderaan de website (dat kun je uitzetten bij <strong>Footer</strong>) en in een contactblok, als je dat op een pagina zet. <strong>Gebruik een adres dat je echt leest.</strong>",
    'help.settings.phone' => "Een telefoonnummer waarop mensen je kunnen bereiken.\n\nHet staat onderaan de website als je dat aanzet bij <strong>Footer</strong>. Laat het leeg als je niet gebeld wilt worden.",
    'help.settings.city' => "De plaats of regio die bezoekers bij je contactgegevens zien, bijvoorbeeld naast een contactformulier. Laat je het leeg, dan verschijnt die regel niet.\n\nDit is geen postadres. Dat vul je hieronder in bij <strong>Adresgegevens</strong>.",
    'help.settings.address' => "Vul alleen in wat je op je website of in zakelijke documenten wilt gebruiken. Voor een gewone website zijn deze gegevens niet verplicht.",
    'help.settings.company_city' => "De plaats die bij je adres hoort. Vul je hem in, dan staat hij ook onderaan de e-mails die de website verstuurt.",
    'help.settings.country' => "Het land van je adres, als code van twee letters: <strong>NL</strong> voor Nederland, <strong>BE</strong> voor België. Laat je het leeg, dan wordt NL gebruikt.",
    'help.settings.primary_language' => "Je website bestaat in het Nederlands en in het Engels. Hier kies je welke van de twee een bezoeker als eerste ziet.\n\nOntbreekt ergens een vertaling, dan toont de website op die plek de tekst in deze taal. Het CMS zelf verandert hier niet van taal: dat stel je in bij <strong>Mijn account</strong>.",
    'help.settings.seo_description' => "Een <strong>meta description</strong> is een korte omschrijving van een pagina. Zoekmachines zoals Google tonen hem vaak onder de titel in hun zoekresultaten; op de website zelf zie je hem niet.\n\nElke pagina kan een eigen omschrijving krijgen. Deze standaardtekst wordt alleen gebruikt op pagina's die er zelf geen hebben. Heb je niets algemeens te zeggen, laat hem dan leeg: overal dezelfde zin helpt niemand.",
    'help.settings.robots' => "Zoekmachines zoals Google bezoeken websites om hun pagina's in de zoekresultaten op te nemen. Dat heet <strong>indexeren</strong>.\n\nStaat deze schakelaar aan, dan mag dat. Zet hem alleen uit zolang je website nog niet klaar is en nog niet gevonden mag worden, en zet hem weer aan zodra de website live gaat. Uit vraagt zoekmachines om geen enkele pagina op te nemen.",
    'help.pages.overview' => "Hier beheer je de pagina's van je website. Klik op een pagina om de inhoud of instellingen te wijzigen.",
    'help.page.seo' => "Met deze gegevens bepaal je hoe zoekmachines, zoals Google, deze pagina kunnen begrijpen, en vaak ook hoe de pagina in de zoekresultaten wordt weergegeven. Op de pagina zelf zie je ze niet.\n\nAlles hier is optioneel. Laat je een veld leeg, dan gebruikt de website een standaard.",
    'help.page.seo_title' => "De titel van de pagina in de zoekresultaten en in het tabblad van de browser. Beschrijf duidelijk waar de pagina over gaat en zet het belangrijkste onderwerp vooraan.\n\nSchrijf voor mensen: dezelfde zoekwoorden steeds herhalen helpt niet. Laat je het veld leeg, dan wordt de titel automatisch <strong>Titel van de pagina — :site</strong>.",
    'help.page.meta_description' => "Een korte samenvatting van de pagina, in een of twee zinnen, die iemand in de zoekresultaten laat zien waar de pagina over gaat. In technische termen heet dit de <em>meta description</em>.\n\nZoekmachines tonen hem vaak onder de titel, maar kunnen ook zelf een ander stukje tekst van de pagina kiezen. Laat je het veld leeg, dan gebruikt de website de standaardomschrijving uit Instellingen, als die is ingevuld.",
    'help.page.url' => "Het webadres is het laatste deel van de URL van deze pagina. Bij <strong>mijnsite.nl/contact</strong> is <strong>contact</strong> het webadres. In technische termen heet dit de <em>slug</em>.\n\nHet menu, de footer en de knop in de header verwijzen naar de pagina zelf, niet naar dit adres. Die links gaan dus vanzelf mee als het adres verandert.",
    'help.page.url_new' => "Het webadres is het laatste deel van de URL van deze pagina. Bij <strong>mijnsite.nl/contact</strong> is <strong>contact</strong> het webadres. In technische termen heet dit de <em>slug</em>.\n\nZolang je dit veld niet zelf aanpast, maakt het CMS het adres uit de titel. Is dat adres al in gebruik, dan komt er een nummer achter. Tot de pagina bestaat kun je het vrij aanpassen; daarna is het beschermd tegen per ongeluk wijzigen.",
    'help.page.show_breadcrumb' => "Het kruimelpad is de kleine regel bovenaan de pagina die laat zien waar een bezoeker is, bijvoorbeeld <strong>Home / Contact</strong>.

De naam die erin staat is de titel van deze pagina: hernoem je de pagina, dan verandert het kruimelpad mee. Zet je dit uit, dan verdwijnt de regel van deze pagina; de rest van de pagina blijft zoals hij is.",
    'help.page_hero.eyebrow' => "Een kort woord of zinnetje in kleine hoofdletters boven de titel, bijvoorbeeld het onderwerp van de pagina.\n\nLaat je het leeg, dan staat er niets boven de titel.",
    'help.page_hero.title' => "De grote kop bovenaan de pagina, en de belangrijkste titel ervan: zoekmachines en voorleessoftware lezen hem als eerste.",
    'help.page_hero.lead' => "Eén of twee zinnen onder de titel die vertellen waar de pagina over gaat.\n\nLaat je het leeg, dan staat er geen tekst onder de titel.",
    'help.page_hero.content_position' => "Waar de titel en de tekst in de kop staan: links, in het midden of rechts. Links is hoe een paginakop er altijd uitzag.\n\nEen achtergrondfoto blijft de hele breedte vullen; alleen de tekst verschuift. Naast een foto verschuift de tekst binnen zijn eigen kolom.",
    'help.page_hero.title_size' => "<strong>Normaal</strong> past bij de meeste pagina's. Kies <strong>Klein</strong> voor een lange titel en <strong>Groot</strong> voor een korte.\n\nOp een telefoon wordt een titel nooit groter dan normaal, zodat lange woorden blijven passen.",
    'help.page_hero.text_size' => "Hoe groot de inleiding onder de titel is. <strong>Normaal</strong> past bij de meeste pagina's.",
    'help.page_hero.is_active' => "Staat dit uit, dan verdwijnt de paginakop van de pagina. Er gaat niets verloren: zet je het weer aan, dan staat alles er weer.",
    'help.page_hero.image_mode' => "Waar de afbeelding staat.\n\nBij <strong>Achtergrond</strong> vult de foto de hele kop, met een waas erover zodat de tekst leesbaar blijft, en staat het kruimelpad over de foto. Bij <strong>Links van de tekst</strong> of <strong>Rechts van de tekst</strong> staat de foto in een vaste liggende vorm naast de tekst; op een telefoon staat hij dan altijd boven de tekst.\n\nKies je <strong>Geen afbeelding</strong>, dan wordt een gekozen afbeelding bij het opslaan losgemaakt van de kop. In de mediabibliotheek blijft hij gewoon staan.",
    'help.page_hero.hero_height' => "Hoe hoog de kop met een achtergrondfoto minstens is. <strong>Middel</strong> is de hoogte die een paginakop met foto altijd had. Een lange titel of inleiding maakt de kop vanzelf hoger.\n\nOp een telefoon zijn alle drie lager, zodat onder de kop nog iets van de pagina te zien is.",
    'help.page_hero.image_alt' => "Wat een schermlezer over de foto naast de tekst voorleest. Staat hier de tekst uit de mediabibliotheek, dan volgt deze kop die tekst; pas je hem aan, dan geldt jouw tekst alleen hier.\n\nEen achtergrondfoto wordt niet voorgelezen: die zet de sfeer, en de tekst van de kop zegt al waar de pagina over gaat.",
    'help.portfolio.overview' => 'Hier beheer je je portfolio: de items en hun categorieën. Waar de items op de website verschijnen, bepaal je met een galerijblok op een pagina.',
    'help.portfolio.new_item' => 'Een afbeelding is genoeg. Alt-tekst, titel, korte tekst en categorie mogen leeg blijven en vul je later aan wanneer je wilt. Na het aanmaken kun je het item ook een eigen projectpagina geven, met tekst en extra afbeeldingen.',
    'help.portfolio.image' => 'De afbeelding is het portfolio-item. Kies hem uit de mediabibliotheek, of upload daar een nieuw bestand. Hij wordt pas aan dit item gekoppeld als je het item aanmaakt.',
    'help.portfolio.replace_image' => 'Kies een andere afbeelding uit de mediabibliotheek, of upload daar een nieuwe. De huidige blijft staan tot je op Opslaan klikt.',
    'help.portfolio.alt' => 'Een schermlezer leest deze tekst voor aan wie de afbeelding niet kan zien. Beschrijf de afbeelding wanneer deze inhoudelijke informatie bevat. Is de afbeelding alleen decoratief, dan mag dit veld leeg blijven.',
    'help.portfolio.title' => 'De naam van het werk. Bezoekers zien hem op de afbeelding in de galerij. Mag leeg blijven.',
    'help.portfolio.subtitle' => 'Een korte regel onder de titel, bijvoorbeeld het materiaal of de opdrachtgever. Staat op de afbeelding in de galerij en bovenaan de projectpagina. Mag leeg blijven.',
    'help.portfolio.categories' => 'Met categorieën kunnen bezoekers de galerij filteren. Vink er één of meer aan, of geen: een item zonder categorie blijft gewoon zichtbaar onder "Alles".',
    'help.portfolio.visible' => 'Uit: het item blijft bewaard, maar staat in geen enkele galerij op de website.',
    'help.forms.overview' => "Een formulier maak je hier één keer en plaats je daarna met het blok <strong>Formulier</strong> op zoveel pagina's als je wilt. Staat een formulier uit, dan is het op geen enkele pagina te zien en neemt de website er geen inzendingen voor aan.",
    'help.forms.active' => "Aan: het formulier staat op elke pagina waar je het met een blok hebt geplaatst, en bezoekers kunnen het versturen.\n\nUit: het formulier verdwijnt van die pagina's en de website neemt er geen inzendingen meer voor aan, ook niet van iemand die de pagina nog open had staan. De velden, de instellingen en de bewaarde inzendingen blijven gewoon staan. Zet je het weer aan, dan werkt het meteen zoals voorheen.",
    'help.forms.name' => "Alleen voor jezelf: aan deze naam herken je het formulier in het overzicht en als je het in een blok kiest. Bezoekers zien hem niet.",
    'help.forms.thank_you_message' => "De tekst die de bezoeker ziet in plaats van het formulier, zodra het versturen gelukt is. Laat je hem leeg, dan staat er <strong>Bedankt — je bericht is verstuurd.</strong>",
    'help.forms.notification_email' => "Elke keer dat iemand dit formulier verstuurt, krijgt dit adres een e-mail met de antwoorden. Laat je het leeg, dan gaat die e-mail naar het e-mailadres uit Instellingen.",
    'help.forms.store_submissions' => "Aan: elke inzending wordt ook in het CMS bewaard. Je leest ze terug onder <strong>Inzendingen</strong>, en een inzending gaat niet verloren als het mailen van de melding mislukt.\n\nUit: de e-mail is de enige plek waar een inzending aankomt. Wat de bezoeker invulde wordt niet in de database bewaard, en lukt het mailen niet, dan krijgt de bezoeker een foutmelding in plaats van een bedankje.\n\nBewaarde inzendingen zijn persoonsgegevens. Alleen wie het recht <strong>Formulierinzendingen bekijken</strong> heeft, kan ze lezen. Ze blijven staan tot je ze zelf verwijdert, ook als je deze instelling later uitzet.",
    'help.forms.field_label' => "Wat de bezoeker bij het veld leest, zoals <strong>Je naam</strong> of <strong>Waar gaat je vraag over?</strong>

Uit het eerste label maakt het CMS ook de vaste naam waaronder antwoorden worden bewaard. Het label zelf kun je later gewoon wijzigen.",
    'help.forms.field_help' => "Een korte toelichting onder het label, zoals <strong>We bellen alleen als je daarom vraagt</strong>. Laat hem leeg als het label genoeg zegt.",
    'help.forms.field_placeholder' => "Lichtgrijze tekst in het veld zolang de bezoeker nog niets heeft getypt, zoals <strong>naam@voorbeeld.nl</strong>. Hij verdwijnt zodra de bezoeker typt en wordt nooit meegestuurd. In technische termen heet dit een <em>placeholder</em>.",
    'help.forms.field_required' => "Aan: het formulier wordt pas verstuurd als de bezoeker dit veld heeft ingevuld. Bij een selectievakje betekent dat: aangevinkt.\n\nUit: de bezoeker mag het leeg laten.",
    'help.forms.reply_to' => "Kies een e-mailveld van dit formulier. Klik je in je e-mailprogramma bij de melding op <strong>Beantwoorden</strong>, dan gaat je antwoord meteen naar het adres dat de bezoeker invulde.\n\nKies je niets, dan gaat een antwoord naar het adres van de website zelf. De afzender van de melding is altijd de website; een bezoeker kan die niet veranderen. In technische termen heet dit het <em>Reply-To</em>-adres.",

