    'shop_settings.email_title' => 'Bevestigingsmail na een bestelling',
    'shop_settings.placeholders' => 'Invulvelden',
    'shop_settings.email_subject' => 'Onderwerp',
    'shop_settings.email_heading' => 'Kop',
    'shop_settings.email_intro' => 'Openingstekst',
    'shop_settings.email_before_items' => 'Tekst boven het productoverzicht',
    'shop_settings.email_after_items' => 'Tekst onder het productoverzicht',
    'shop_settings.email_closing' => 'Afsluittekst',
    'shop_settings.email_signature' => 'Ondertekening',
    'shop_settings.restore_defaults' => 'Herstel standaardtekst',
    'shop_settings.restore_defaults_confirm' => 'De standaardtekst in alle velden van deze e-mail zetten? Je eigen tekst blijft bewaard tot je op Opslaan klikt.',
    'shop_settings.restore_defaults_done' => 'De standaardtekst staat in de velden. Klik op Opslaan om hem te gebruiken, of verlaat de pagina om je eigen tekst te houden.',
    'shop_settings.warning_no_sender' => 'Bevestigingsmails kunnen nu niet worden verstuurd: er is geen e-mailadres om ze vanaf te sturen. Vul een e-mailadres in bij <a href="/admin/settings.php">Instellingen</a>.',
    'shop_settings.warning_no_notification_address' => 'Bevestigingsmails worden nu niet verstuurd: er is geen adres ingesteld waar de webshop een melding van elke nieuwe bestelling naartoe stuurt. Dat adres staat in de configuratie van de server (SHOP_NOTIFICATION_EMAIL), niet in het CMS. Vraag degene die je website host of bouwt om het in te stellen.',
    'help.shop_settings.intro' => "Hier regel je wat alleen voor je webshop nodig is: de gegevens op facturen, het bestelnummer en de e-mail die een klant na een bestelling krijgt.\n\nNiets op deze pagina is verplicht. Wat je leeg laat, krijgt een standaardwaarde of komt niet op de factuur.",
    'help.shop_settings.company' => "Deze gegevens komen op elke nieuwe factuur. Een factuur die al gemaakt is, verandert nooit meer mee.",
    'help.shop_settings.company_name' => "De officiële naam van je bedrijf zoals die op een factuur hoort, bijvoorbeeld de naam uit je KVK-inschrijving als die anders is dan de naam van je website.\n\nLaat je het leeg, dan staat de <strong>naam van de website</strong> op de factuur.",
    'help.shop_settings.vat_id' => "Je btw-identificatienummer, als je dat hebt, bijvoorbeeld NL123456789B01.\n\nHoef je geen btw te rekenen, bijvoorbeeld omdat je de kleineondernemersregeling gebruikt, laat het dan leeg.",
    'help.shop_settings.website' => "Het webadres dat op de factuur staat, bijvoorbeeld www.jouwwinkel.nl. Laat het leeg als je dat niet wilt.",
    'help.shop_settings.invoices' => "Een factuur maakt de webshop zelf, zodra een bestelling betaald is. Hier bepaal je het begin van het factuurnummer en een paar vaste teksten op de factuur.",
    'help.shop_settings.invoice_prefix' => "De letters vóór elk factuurnummer. Met <strong>INV</strong> ziet een factuurnummer eruit als INV2026-000001: het jaar en het volgnummer zet de webshop er zelf achter. Wil je een streepje tussen de letters en het jaar, typ dan <strong>INV-</strong>.\n\nGebruik letters, cijfers, - en _ (maximaal 20 tekens, en begin met een letter of cijfer); een / of : kan niet, omdat het factuurnummer ook de naam van het PDF-bestand is. Laat je het leeg, dan wordt INV gebruikt. Een wijziging geldt alleen voor nieuwe facturen.",
    'help.shop_settings.invoice_tax_note' => "Een vaste zin over btw of andere regels die op elke factuur moet staan, bijvoorbeeld dat je de kleineondernemersregeling (KOR) gebruikt.\n\nVul dit alleen in als je zeker weet wat erin hoort. Laat je het leeg, dan staat er niets.",
    'help.shop_settings.invoice_payment_note' => "Een korte zin over de betaling, bijvoorbeeld <em>Betaald via iDEAL.</em> Laat je het leeg, dan staat er niets.",
    'help.shop_settings.invoice_footer_text' => "Kleine tekst helemaal onderaan de factuur, bijvoorbeeld een bedankje. Laat je het leeg, dan staat er niets.",
    'help.shop_settings.order_prefix' => "De letters of cijfers vóór elk bestelnummer. Met <strong>ORD</strong> ziet een bestelnummer eruit als ORD-2026-000127. Je klant ziet het in de e-mail, bij het betalen en op de factuur.\n\nAlleen letters en cijfers, hoogstens 10 tekens. Laat je het leeg, dan wordt ORD gebruikt. Een bestelling houdt het nummer dat ze kreeg: een wijziging geldt alleen voor nieuwe bestellingen.",
    'help.shop_settings.email' => "Deze e-mail krijgt een klant zodra de betaling gelukt is. Jij schrijft de teksten eromheen. Het productoverzicht, de prijzen, de adressen en de factuur voegt de webshop zelf toe, zodat die altijd kloppen.",
    'help.shop_settings.placeholders' => "Invulvelden zijn woorden tussen dubbele accolades. De webshop vervangt ze in elke e-mail door de gegevens van die bestelling, en je kunt ze in alle velden van deze e-mail gebruiken.\n\nTyp ze precies over, met de accolades erbij. Een woord tussen accolades dat hieronder niet staat, blijft gewoon als tekst in de e-mail staan.",
    'help.shop_settings.placeholder.customer_name' => "De naam van de klant, zoals die bij het afrekenen is ingevuld: voornaam en achternaam.",
    'help.shop_settings.placeholder.order_number' => "Het nummer van de bestelling, bijvoorbeeld ORD-2026-000127.",
    'help.shop_settings.placeholder.order_date' => "De datum van de bestelling, bijvoorbeeld 14-03-2026.",
    'help.shop_settings.placeholder.order_total' => "Het totaalbedrag van de bestelling, inclusief verzendkosten, bijvoorbeeld € 54,90.",
    'help.shop_settings.placeholder.site_name' => "De naam waaronder de webshop e-mail verstuurt. Meestal is dat de naam van je website uit Instellingen.",
