    // Header & navigatie (admin/navigation.php, admin/navigation-item.php): Navigation phase A.
    'help.navigation.overview' => "Het <strong>menu</strong> en de <strong>knoppen</strong> staan bovenaan elke pagina van je website. Op een telefoon verschijnen ze allebei zodra een bezoeker op het menu-icoon tikt.\n\nZet de volgorde met de pijltjes. Een item dat je verbergt, blijft bewaard. Wijst een link naar een pagina die op concept staat of naar een onderdeel dat uit staat, dan verdwijnt hij tijdelijk van de website en komt hij vanzelf terug.",
    'help.navigation.visible' => 'Staat dit uit, dan verdwijnt het item van de website maar blijft het hier bewaard. Zo haal je iets tijdelijk weg zonder het opnieuw te hoeven maken.',
    'help.navigation.text' => 'De woorden die bezoekers in de header zien. Houd het kort: een lange tekst neemt veel ruimte in, zeker op een knop. Laat je de vertaling leeg, dan gebruikt de website de tekst in de hoofdtaal.',
    'help.navigation.label_follows' => "Staat dit aan, dan toont het menu de titel van de gekozen pagina, in elke taal van je website. Verander je later de titel van die pagina, dan verandert het menu vanzelf mee.\n\nZet je het uit, dan schrijf je een eigen tekst, per taal.",
    'help.navigation.destination' => 'Kies <strong>een pagina van deze website</strong> voor een pagina die je zelf beheert: de link gaat mee als je het adres van die pagina later verandert. <strong>Een vast onderdeel</strong> is een deel van de website dat geen gewone pagina is, zoals de winkelwagen. <strong>Een ander adres</strong> is voor een andere website.',
    'help.navigation.route' => 'Delen van de website die geen gewone pagina zijn, zoals de homepage, de winkel en de winkelwagen. Een onderdeel dat uit staat, kun je hier niet kiezen.',
    'help.navigation.external' => 'Een volledig adres dat begint met https://, of een adres op deze website dat begint met een schuine streep, zoals /contact.',
    'help.navigation.new_tab' => 'Handig voor een andere website: je eigen website blijft dan open. Voor een pagina van je eigen website is het meestal niet nodig.',
    'help.navigation.presentation' => 'Een <strong>link</strong> staat in het menu. Een <strong>knop</strong> staat rechts in de header en valt meer op: gebruik hem voor de één of twee dingen die bezoekers vooral moeten doen, zoals contact opnemen.',
    'help.navigation.variant' => 'Opvallend is een gevulde knop in de hoofdkleur van je website. Rustig heeft alleen een rand. Heb je twee knoppen, maak er dan één opvallend en één rustig.',
