    'shop.editor.images_count' => 'afbeeldingen',
    'shop.editor.variants_count' => 'varianten',
    'shop.editor.variants_after_create' => 'Opties en varianten voeg je toe zodra het product is aangemaakt: sla het eerst op, dan opent dit scherm met alles erop.',
    'shop.editor.variants_intro' => 'Optioneel. Een optie (bijv. "Kleur") heeft waardes (bijv. "Noten", "Berken"); een variant is één combinatie van die waardes, met eventueel een eigen prijs, eigen afbeeldingen uit de afbeeldingen van het product en een eigen beschrijving. De bovenste variant is de standaardvariant. Alles hier wordt bewaard met Opslaan onderaan.',
