    'shop.gallery_transition.slide' => 'Schuiven',
    'help.shop.gallery_transition.shop' => 'Hoe de grote foto op een productpagina wisselt als een bezoeker een andere foto kiest. Geen: de foto verschijnt direct. Vervagen: de oude foto vervaagt in de nieuwe. Schuiven: de nieuwe foto schuift er vanaf de zijkant in. Dit geldt voor elk product dat Standaard van Shop volgt; een product kan in zijn eigen editor iets anders kiezen. Bezoekers die in hun apparaat minder beweging hebben ingesteld, zien altijd een directe wissel. Vegen op een touchscreen werkt bij elke keuze.',
    'help.shop.gallery_transition.product' => 'Hoe de grote foto op de pagina van dit product wisselt. Standaard van Shop volgt de keuze op Shop-instellingen, ook als die later verandert. Kies je hier iets anders, dan houdt dit product die keuze.',
    'validation.gallery_transition_invalid' => 'Kies Geen, Vervagen of Schuiven als overgang.',
    'shop.overview.heading' => 'Productoverzicht',
    'shop.overview.intro' => 'De Shop maakt niet vanzelf een pagina met alle producten. Kies hier welke pagina je productoverzicht is, of dat er geen is. Alleen een pagina met een Productgrid-blok kan het overzicht zijn: voeg eerst een Productgrid toe aan de gewenste pagina (Pagina\'s → de pagina → Blok toevoegen), op de plek waar de producten moeten komen. Productpagina\'s, de winkelwagen en het kruimelpad linken daarna naar die pagina.',
    'shop.overview.label' => 'Productoverzicht',
    'shop.overview.help' => 'Productpagina\'s, de winkelwagen en het kruimelpad linken naar deze pagina. Het oude adres /shop.php stuurt bezoekers erheen. Bij Geen overzichtspagina linkt niets naar een overzicht en geeft /shop.php \'niet gevonden\'.',
    'shop.overview.none' => 'Geen overzichtspagina',
    'shop.overview.builtin' => 'Automatisch overzicht op /shop.php (oud gedrag)',
    'shop.overview.page_option' => 'Bestaande pagina: :title',
    'shop.overview.page_option_draft' => 'Bestaande pagina: :title (concept)',
    'shop.overview.builtin_note' => 'Deze site toont nog het automatische overzicht van vóór deze instelling. Kies een eigen pagina om zelf te bepalen wat erop staat; het automatische overzicht kun je daarna niet opnieuw kiezen.',
    'shop.overview.draft_note' => 'De gekozen pagina is nog een concept. Zolang hij niet gepubliceerd is, linkt niets ernaartoe.',
    'shop.overview.no_grid_note' => 'Op deze pagina staat (nog) geen zichtbaar Productgrid, dus hij toont geen producten. Voeg het blok toe in de pagina-editor, of kies een andere pagina.',
