    'nav.payments' => 'Betalingen',
    'payments.title' => 'Betalingen',
    'payments.title_admin' => 'Betalingen — Admin',
    'help.payments.intro' => "Hier koppel je je webshop aan Mollie, het bedrijf dat de betalingen van je klanten verwerkt (iDEAL, creditcard en meer).\n\nJe begint in testmodus: dan kun je alles uitproberen zonder dat er echt geld wordt overgemaakt. Pas als dat werkt, zet je de webshop live.",
    'payments.status.title' => 'Status',
    'payments.status.badge.not_configured' => 'Niet ingesteld',
    'payments.status.badge.test' => 'Testmodus',
    'payments.status.badge.live' => 'Live',
    'payments.status.badge.problem' => 'Probleem',
    'payments.status.lead.not_configured' => 'Je webshop kan nog geen betalingen aannemen. Volg de stappen hieronder om Mollie te koppelen; meestal ben je binnen een kwartier klaar.',
    'payments.status.lead.test' => 'Je webshop is gekoppeld in testmodus. Afrekenen werkt, maar er wordt geen echt geld overgemaakt. Gebruik dit om alles uit te proberen.',
    'payments.status.lead.live' => 'Je webshop neemt echte betalingen aan. Het geld komt binnen op je Mollie-rekening.',
    'payments.status.lead.problem' => 'Er is een sleutel ingesteld, maar de verbinding met Mollie werkt niet. Klanten kunnen nu niet betalen. Hieronder staat wat er mis is.',
    'payments.status.lead.problem_url' => 'De live-sleutel werkt, maar met het webadres van deze site kan Mollie geen echte betalingen afhandelen. Klanten kunnen nu niet betalen. Hieronder staat wat er mis is.',
    'payments.status.provider' => 'Betaalprovider',
    'payments.status.mode' => 'Modus',
