    'payments.status.key_none' => 'Nog geen sleutel voor deze modus',
    'payments.status.connection' => 'Verbinding',
    'payments.status.connection_none' => 'Nog niet getest: er is geen sleutel',
    'payments.status.setup_cta' => 'Mollie instellen',
    'payments.test_connection' => 'Verbinding testen',
    'payments.testing' => 'Bezig met testen…',
    'payments.test_failed_request' => 'De test kon niet worden uitgevoerd. Ben je nog ingelogd? Probeer het opnieuw.',
    'payments.result.ok_test' => 'Verbinding geslaagd. Deze testsleutel werkt. Betaalmethoden die Mollie voor je account aanbiedt: :count.',
    'payments.result.ok_live' => 'Verbinding geslaagd. Deze live-sleutel werkt. Betaalmethoden die Mollie voor je account aanbiedt: :count.',
    'payments.result.no_key' => 'Er is nog geen sleutel om te testen. Plak eerst je API-sleutel in het veld.',
    'payments.result.key_format' => 'Dit is geen Mollie API-sleutel. Een sleutel begint met test_ of live_ en is ongeveer 35 tekens lang, zonder spaties. Kopieer hem opnieuw uit je Mollie-dashboard.',
    'payments.result.unreadable' => 'De opgeslagen sleutel kan niet meer worden gelezen, bijvoorbeeld omdat de site naar een andere server is verhuisd. Plak de sleutel opnieuw en sla op.',
    'payments.result.refused' => 'Mollie weigert deze sleutel. Controleer of je de hele sleutel hebt gekopieerd en of hij in je Mollie-dashboard nog bestaat.',
    'payments.result.unreachable' => 'Mollie is op dit moment niet bereikbaar. Dat ligt meestal niet aan jou; probeer het over een paar minuten opnieuw.',
    'payments.result.unexpected' => 'Mollie gaf een onverwacht antwoord. Probeer het later opnieuw. Blijft dit gebeuren, vraag dan je webbouwer om in het serverlog te kijken.',
    'payments.setup.title' => 'Mollie koppelen, stap voor stap',
    'payments.setup.intro' => 'Nog nooit een betaalprovider ingesteld? Geen probleem. Loop deze zes stappen van boven naar beneden door; je kunt altijd later verder.',
    'payments.setup.done' => 'Klaar',
    'payments.setup.current' => 'Nu',
    'payments.step1.title' => 'Stap 1 — Maak een Mollie-account',
    'payments.step1.body' => "Mollie verwerkt de betalingen voor je webshop. Maak een account aan op mollie.com en vul je bedrijfsgegevens in. Mollie vraagt je ook je website toe te voegen (een <em>websiteprofiel</em>); vul daar het adres van deze webshop in.\n\nTesten kan meteen. Echte betalingen ontvangen kan pas als Mollie je gegevens heeft gecontroleerd; dat duurt meestal een paar werkdagen.",
    'payments.step1.link' => 'Naar mollie.com (opent in een nieuw tabblad)',
    'payments.step2.title' => 'Stap 2 — Zoek je Test API-sleutel',
    'payments.step2.body' => "Log in op je Mollie-dashboard en ga naar <strong>Ontwikkelaars → API-sleutels</strong> (in het Engels: Developers → API keys). Daar staan twee sleutels:\n\n<strong>Test API-sleutel</strong>: begint met test_. Hiermee doe je oefenbetalingen. Er gaat nooit echt geld over.\n<strong>Live API-sleutel</strong>: begint met live_. Hiermee betalen je klanten echt. Die heb je pas in stap 6 nodig.\n\nKopieer de testsleutel. Behandel een sleutel als een wachtwoord: deel hem met niemand en zet hem niet in een e-mail.",
    'payments.step2.link' => 'Naar je Mollie-dashboard (opent in een nieuw tabblad)',
    'payments.step3.title' => 'Stap 3 — Plak de sleutel hier',
    'payments.step3.body' => 'Plak de testsleutel in het veld <strong>Test API-sleutel</strong> hieronder en klik op Opslaan. Mygdala bewaart de sleutel versleuteld. Daarna zie je alleen nog het begin en de laatste vier tekens, bijvoorbeeld test_••••••••abcd. De hele sleutel wordt nooit meer getoond.',
    'payments.step3.link' => 'Naar de API-sleutels',
    'payments.step4.title' => 'Stap 4 — Test de verbinding',
    'payments.step4.body' => "Klik bij de sleutel op <strong>Test deze sleutel</strong>, of bovenaan op <strong>Verbinding testen</strong>. Mygdala vraagt Mollie dan welke betaalmethoden er voor je account aanstaan. Er wordt niets betaald, geen bestelling gemaakt en niets veranderd.\n\nStaat er Verbinding geslaagd, dan werkt je sleutel.",
    'payments.step5.title' => 'Stap 5 — Doe een testbetaling',
    'payments.step5.body' => 'Bestel iets in je eigen webshop, precies zoals een klant dat doet. Omdat je in testmodus bent, laat Mollie je daarna zelf kiezen hoe de betaling afloopt: betaald, mislukt, geannuleerd of verlopen.',
    'payments.step5.link' => 'Zo doe je een testbetaling',
    'payments.step6.title' => 'Stap 6 — Ga live',
    'payments.step6.body' => "Heeft Mollie je account goedgekeurd? Kopieer dan je <strong>Live API-sleutel</strong> uit het dashboard, plak hem in het veld Live API-sleutel en kies bij <strong>Test of live</strong> voor Live. Klik op Opslaan.\n\nMygdala test de live-sleutel eerst. Alleen als die werkt, gaat je webshop echte betalingen aannemen. Je kunt altijd terug naar testmodus.",
    'payments.step6.link' => 'Naar Test of live',
    'payments.keys.title' => 'API-sleutels',
    'help.payments.keys' => "Een API-sleutel is een soort wachtwoord waarmee je webshop met Mollie praat. Je vindt beide sleutels in je Mollie-dashboard onder <strong>Ontwikkelaars → API-sleutels</strong>.\n\nMygdala bewaart een sleutel versleuteld en laat daarna alleen het begin en de laatste vier tekens zien.",
    'payments.keys.test_label' => 'Test API-sleutel',
    'payments.keys.live_label' => 'Live API-sleutel',
    'help.payments.test_key' => 'Begint met test_. Hiermee doe je oefenbetalingen zonder echt geld. Hier begin je mee.',
    'help.payments.live_key' => 'Begint met live_. Hiermee betalen je klanten echt. Een live-sleutel opslaan zet je webshop nog niet live: dat kies je zelf bij Test of live.',
    'payments.keys.stored' => 'Opgeslagen: :hint (sinds :date)',
    'payments.keys.none' => 'Nog geen sleutel opgeslagen.',
    'payments.keys.unreadable' => 'Er is een sleutel opgeslagen (:hint), maar die kan niet meer worden gelezen. Plak hem opnieuw en sla op.',
    'payments.keys.keep_hint' => 'Laat dit veld leeg om de opgeslagen sleutel te houden. Een nieuwe sleutel vervangt de oude zodra je opslaat.',
    'payments.keys.test_this' => 'Test deze sleutel',
    'payments.keys.placeholder_test' => 'test_…',
    'payments.keys.placeholder_live' => 'live_…',
    'payments.keys.environment_title' => 'Geconfigureerd via serveromgeving',
    'payments.keys.environment_body' => 'De Mollie-sleutel van deze webshop staat in de serveromgeving (MOLLIE_API_KEY in het .env-bestand): :key. Je kunt hem hier niet wijzigen of wissen, en de modus volgt de sleutel: een sleutel die met test_ begint is testmodus, live_ is live. Wil je de sleutels hier beheren? Vraag je webbouwer dan om MOLLIE_API_KEY uit de serveromgeving te halen.',
    'payments.keys.environment_invalid' => 'geen geldige Mollie-sleutel',
    'payments.keys.confirm_live' => 'Ja, vervang de live-sleutel',
    'help.payments.confirm_live' => 'Je webshop is live en heeft al betalingen ontvangen. Na het opslaan lopen nieuwe betalingen via de nieuwe sleutel. Controleer dat die bij hetzelfde Mollie-account hoort; anders kan Mygdala betalingen die nu nog openstaan niet meer bijwerken.',
    'payments.mode.title' => 'Test of live',
    'payments.mode.legend' => 'Modus',
    'help.payments.mode' => 'In testmodus doen jij en je klanten oefenbetalingen zonder echt geld. Live betekent echte betalingen. Live kan pas aan als er een live-sleutel is én die werkt; dat controleert Mygdala bij het opslaan.',
    'payments.mode.test' => 'Testmodus',
    'payments.mode.live' => 'Live',
    'payments.mode.explain' => 'Mygdala zet je webshop nooit vanzelf live, ook niet als er een live-sleutel is opgeslagen. Dat kies je altijd zelf, hier.',
    'payments.mode.environment' => 'De modus volgt de sleutel in de serveromgeving: :mode.',
    'payments.testpay.title' => 'Een testbetaling doen',
    'payments.testpay.intro' => 'Zo probeer je de hele bestelling uit met de echte kassa van je webshop, zonder echt geld. Doe dit alleen in testmodus.',
    'payments.testpay.step1' => 'Controleer bovenaan dat de status Testmodus is.',
    'payments.testpay.step2' => 'Open je webshop met de knop hieronder. Hij opent in een nieuw tabblad.',
    'payments.testpay.step3' => 'Leg een product in de winkelwagen.',
    'payments.testpay.step4' => 'Ga naar afrekenen en vul je gegevens in, zoals een klant dat doet.',
    'payments.testpay.step5' => 'Kies een betaalmethode en plaats de bestelling. Je komt nu bij Mollie.',
    'payments.testpay.step6' => 'In testmodus toont Mollie een testpagina. Kies daar hoe de betaling afloopt: betaald, mislukt, geannuleerd of verlopen. Zo oefen je elke uitkomst.',
    'payments.testpay.step7' => 'Mollie stuurt je terug naar je webshop, waar je ziet hoe de bestelling ervoor staat.',
    'payments.testpay.step8' => 'Kijk in het CMS bij Shop → Bestellingen: daar staat de bestelling met het label TEST en de betaalstatus die je koos. Bij een betaalde testbestelling is de bevestigingsmail verstuurd, gemarkeerd als test en zonder factuur.',
    'payments.testpay.open_shop' => 'Naar de webshop (opent in een nieuw tabblad)',
    'payments.testpay.not_test' => 'De knop naar de webshop verschijnt zodra de status Testmodus is. In Live wordt een bestelling echt betaald.',
    'payments.webhook.title' => 'Webhook',
    'payments.webhook.intro' => 'Mollie laat je webshop via een webhook weten wanneer een betaling verandert, bijvoorbeeld van open naar betaald. Mygdala geeft dit adres bij elke betaling zelf aan Mollie mee. Je hoeft in Mollie dus niets in te stellen.',
    'payments.webhook.url_label' => 'Webhookadres',
    'payments.webhook.copy' => 'Kopiëren',
    'payments.webhook.copied' => 'Gekopieerd',
    'payments.webhook.unreachable' => 'Het webadres van deze site (:base) is niet bereikbaar vanaf internet, bijvoorbeeld omdat de site op je eigen computer draait. Mollie kan zo’n adres niet aanroepen, dus Mygdala geeft dan geen webhook mee. In testmodus is dat geen probleem: een testbestelling wordt bijgewerkt zodra de klant terugkomt op de bestelpagina. Live kan alleen met een openbaar https-adres.',
    'payments.webhook.base_missing' => 'Het webadres van deze site is nog niet ingesteld. Doe dat in de installatiewizard, of vraag je webbouwer om APP_URL in te stellen: anders weet Mollie niet waar je webshop te bereiken is.',
    'payments.webhook.not_https' => 'Je site gebruikt geen https. Voor echte betalingen is een beveiligde verbinding (https) sterk aan te raden.',
    'payments.error.pinned_by_environment' => 'De Mollie-sleutel staat vast in de serveromgeving. Die kun je hier niet wijzigen of wissen.',
    'payments.error.key_format' => 'Dit is geen Mollie API-sleutel. Een sleutel begint met test_ of live_ en is ongeveer 35 tekens lang, zonder spaties.',
    'payments.error.live_key_in_test_field' => 'Dit is een live-sleutel (hij begint met live_). Plak hem in het veld Live API-sleutel.',
