    'payments.error.storage_key_invalid' => 'De sleutel kon niet veilig worden opgeslagen: APP_KEY in de serveromgeving, of het sleutelbestand, is geen geldige sleutel. Vraag je webbouwer om dat na te kijken. Er is niets gewijzigd.',
