    'payments.methods.title' => 'Betaalmethoden',
    'help.payments.methods' => "Mollie bepaalt welke betaalmethoden je <em>kunt</em> aanbieden: de methoden die in je Mollie-dashboard aanstaan. Hier kies je welke daarvan je klanten bij het afrekenen echt zien.\n\nStaat een methode hier niet tussen? Zet hem dan eerst aan in je Mollie-dashboard en kom daarna terug. Testmodus en Live kunnen verschillen: Mollie kan in testmodus methoden tonen die live nog niet zijn goedgekeurd.",
    'payments.methods.intro' => 'Vink aan welke betaalmethoden je klanten bij het afrekenen zien. De lijst komt rechtstreeks van Mollie: alleen wat voor je account aanstaat, kun je aanbieden.',
    'payments.methods.legend' => 'Aangeboden bij het afrekenen',
    'payments.methods.available' => 'Beschikbaar bij Mollie',
    'payments.methods.unavailable' => 'Niet beschikbaar bij Mollie',
    'payments.methods.default_note' => 'Je hebt hier nog niets gekozen. Je webshop biedt daarom iDEAL en creditcard aan, zoals altijd. Een andere methode gaat pas aan als je hem aanvinkt en opslaat.',
    'payments.methods.unknown_note' => 'De verbinding met Mollie werkt nu niet, dus Mygdala weet niet welke methoden beschikbaar zijn. Je kunt methoden uitzetten; nieuwe aanzetten kan zodra de verbinding werkt.',
    'payments.methods.mode_note' => 'Deze lijst hoort bij :mode. Testmodus en Live kunnen verschillende methoden hebben.',
    'payments.methods.unavailable_note' => 'Een aangevinkte methode die Mollie niet (meer) aanbiedt, kan een klant niet gebruiken: het afrekenen mislukt dan. Zet hem uit, of zet hem aan in je Mollie-dashboard.',
    'payments.error.methods_none' => 'Kies minstens één betaalmethode. Zonder betaalmethode kan niemand afrekenen.',
    'payments.error.methods_invalid' => 'Er is een onbekende betaalmethode verstuurd. Laad de pagina opnieuw en probeer het nog eens.',
    'payments.error.methods_unverifiable' => 'Mollie is nu niet te bereiken, dus nieuwe betaalmethoden kunnen niet worden gecontroleerd. Je kunt methoden uitzetten; aanzetten kan zodra de verbinding werkt.',
    'payments.error.method_unavailable' => 'De betaalmethode :method staat niet aan in je Mollie-account. Zet hem eerst aan in je Mollie-dashboard.',
    'validation.factuurprefix_ongeldig' => 'Het voorvoegsel van het factuurnummer mag alleen letters, cijfers, - en _ bevatten, moet met een letter of cijfer beginnen en is maximaal 20 tekens lang.',
    'shop_settings.invoice_prefix_legacy' => 'Het huidige voorvoegsel ":prefix" bevat tekens die niet in een factuurnummer mogen, zoals / of :. Nieuwe facturen gebruiken daarom ":used". Bestaande facturen blijven precies zoals ze zijn. Kies een voorvoegsel met alleen letters, cijfers, - en _ om dit op te lossen.',
    'payments.testpay.note' => 'Goed om te weten: een testbestelling staat in Shop → Bestellingen met het label TEST. Ze telt niet mee in de omzet op het dashboard en krijgt nooit een factuur, zodat je echte factuurnummers aaneengesloten blijven. Ze krijgt wel een bestelnummer en een bevestigingsmail, gemarkeerd als test. Ook na de overstap naar Live blijft een testbestelling een testbestelling.',
    'perm.payments.manage.label' => 'Betalingen beheren',
    'perm.payments.manage.description' => 'De Mollie-sleutels, test of live en de betaalmethoden. Bepaalt op welk Mollie-account klanten betalen; alleen een Super Admin kan dit toekennen.',
    'shop.test_badge' => 'TEST',
