    // --- Detailsectie 2.0: anchors, the main image, gallery sources (admin/detail-section.php) ---
    'help.block_detail.anker' => 'Een woord waarmee de sectie te bereiken is: bij "hout" wordt het adres van de sectie #hout. Kleine letters, cijfers en streepjes; een # en spaties worden vanzelf aangepast. De sectie verschijnt dan automatisch in de ankernavigatie onder de kop van de pagina, met het navigatielabel. Twee secties op één pagina kunnen niet hetzelfde anker hebben. Leeg = geen anker.',
    'help.block_detail.navigatielabel' => 'De korte tekst van deze sectie in de ankernavigatie. Leeg = de titel. Per taal.',
    'help.block_detail.slotnotitie' => 'Optionele extra tekst onderaan de sectie. Leeg laten = geen slotnotitie.',
    'help.block_detail.cta' => 'Knoptekst en URL horen bij elkaar: is er maar één van de twee ingevuld, dan wordt er geen knop getoond.',
    'help.block_detail.hoofdafbeelding' => 'Optioneel. Staat naast de tekst, aan de kant die je bij Beeldpositie kiest. Zonder hoofdafbeelding blijft de sectie tekst met de kenmerken ernaast.',
    'help.block_detail.beeldpositie' => 'Aan welke kant van de tekst de hoofdafbeelding staat. Op een telefoon staat hij altijd onder de tekst. Dit is de plek van de afbeelding in de sectie, geen focuspunt: de hoofdafbeelding wordt nooit bijgesneden en toont altijd de hele foto.',
    'help.block_detail.kenmerken' => 'Korte punten naast de tekst, elk met een vast vinkje-icoon.',
    'help.block_detail.galerij' => 'Optioneel: een rij afbeeldingen onder de sectie. Elk item is een afbeelding uit de mediabibliotheek, of een product, project of blogbericht: dat toont zijn eigen afbeelding en naam en linkt naar zijn pagina. Op een telefoon staat er één item tegelijk in beeld, met pijlen. Elk item staat in een vierkant; met Focuspunt kies je per item welk deel van de foto zichtbaar is.',
    'block_detail.galerij_item' => 'Item',
    'block_detail.error_anker' => 'Een anker bestaat uit letters, cijfers en streepjes, bijvoorbeeld "hout".',
    'block_detail.error_anker_dubbel' => 'Een andere detailsectie op deze pagina heeft het anker "#:anchor" al. Kies een ander.',
    'gallery_source.source' => 'Bron',
    'help.gallery_source.source' => 'Een afbeelding uit de mediabibliotheek, of een product, project of blogbericht van deze site. Dat toont altijd zijn huidige afbeelding en naam en linkt naar zijn pagina; zolang het niet openbaar is, staat het niet op de website.',
